class TestPreRelease:
    def test_alpha(self):
        assert canonicalize_version("1.0a1") == "1.0a1"

    def test_beta(self):
        assert canonicalize_version("1.0b2") == "1.0b2"

    def test_rc(self):
        assert canonicalize_version("1.0rc1") == "1.0rc1"

    def test_alpha_with_trailing_zeros(self):
        assert canonicalize_version("1.0.0a1") == "1.0a1"

    def test_alpha_no_strip(self):
        assert canonicalize_version("1.0.0a1", strip_trailing_zero=False) == "1.0.0a1"

    def test_alpha_implicit_number(self):
        assert canonicalize_version("1.0alpha") == "1.0a0"

    def test_beta_implicit_number(self):
        assert canonicalize_version("1.0beta") == "1.0b0"

    def test_rc_implicit_number(self):
        assert canonicalize_version("1.0rc") == "1.0rc0"

    def test_pre_normalized(self):
        """Pre-release identifiers are normalized (alpha->a, beta->b, etc.)."""
        assert canonicalize_version("1.0.0alpha1") == "1.0a1"

    def test_pre_normalized_beta(self):
        assert canonicalize_version("1.0.0beta2") == "1.0b2"

    def test_pre_normalized_preview(self):
        assert canonicalize_version("1.0.0preview1") == "1.0rc1"

    def test_pre_normalized_c(self):
        assert canonicalize_version("1.0.0c1") == "1.0rc1"

    def test_pre_normalized_pre(self):
        assert canonicalize_version("1.0.0pre1") == "1.0rc1"

    def test_pre_normalized_rev(self):
        # "rev" normalizes to "post", not a pre-release
        assert canonicalize_version("1.0.0rev1") == "1.0.post1"

