class TestEpoch:
    def test_epoch_simple(self):
        assert canonicalize_version("1!1.0") == "1!1"

    def test_epoch_with_trailing_zeros(self):
        assert canonicalize_version("1!1.0.0") == "1!1"

    def test_epoch_no_strip(self):
        assert canonicalize_version("1!1.0.0", strip_trailing_zero=False) == "1!1.0.0"

    def test_epoch_with_pre(self):
        assert canonicalize_version("1!1.0a1") == "1!1.0a1"

    def test_epoch_with_post(self):
        assert canonicalize_version("1!1.0.post1") == "1!1.0.post1"

    def test_epoch_with_dev(self):
        assert canonicalize_version("1!1.0.dev1") == "1!1.0.dev1"

    def test_epoch_with_local(self):
        assert canonicalize_version("1!1.0+ubuntu") == "1!1.0+ubuntu"

    def test_epoch_zero(self):
        """Epoch of 0 is not printed."""
        assert canonicalize_version("0!1.0") == "1"
